    search = request.GET.get('search', '').strip()
    status_filter = request.GET.get('status', '').strip()
    
    # 获取可打卡的拜访计划（未打卡的）
    visit_plans = VisitPlan.objects.all().select_related('client', 'created_by', 'related_opportunity').order_by('-plan_date')
    
