    if status_filter:
        visit_plans = visit_plans.filter(status=status_filter)
    
    # 排除已完成的打卡
    visit_plans = visit_plans.exclude(
        id__in=VisitCheckin.objects.values_list('visit_plan_id', flat=True)
    )
    
