    # 获取当前步骤
    current_step = visit_plan.get_current_step()
    
    # 获取打卡记录
    checkin = visit_plan.checkins.first()
    
    # 获取复盘记录
    try:
        review = visit_plan.review
    except VisitReview.DoesNotExist:
        review = None
    
    context = _context(
        f"拜访计划详情 - {visit_plan.plan_title}",
        "📋",
        f"客户：{visit_plan.client.name}",
        request=request,
    )
    
